✔ Veja o estado e o histórico das encomendas','VAT number field visibilityHidden' => 'Oculto','VAT number field visibilityOptional' => 'Opcional','VAT number field visibilityRequired' => 'Obrigatório','Delivery typeShipping to address' => 'Envio para a morada','Delivery typeLocal pickup' => 'Recolha no local',] ];